class Solution:
    def kthSmallestPath(self, destination: List[int], k: int) -> str:
        row, col = destination
        count = 0
        answer = ''
        path = []

        def dfs(h: int, v: int) -> None:
            nonlocal count, answer
            if answer:
                return
            if h == 0 and v == 0:
                count += 1
                if count == k:
                    answer = ''.join(path)
                return
            if h > 0:
                path.append('H')
                dfs(h - 1, v)
                path.pop()
                if answer:
                    return
            if v > 0:
                path.append('V')
                dfs(h, v - 1)
                path.pop()

        dfs(col, row)
        return answer

