class Solution {
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int row = destination[0], col = destination[1];
        string path, answer;
        int count = 0;

        function<void(int, int)> dfs = [&](int h, int v) {
            if (!answer.empty()) return;
            if (h == 0 && v == 0) {
                if (++count == k) answer = path;
                return;
            }
            if (h > 0) {
                path.push_back('H');
                dfs(h - 1, v);
                path.pop_back();
                if (!answer.empty()) return;
            }
            if (v > 0) {
                path.push_back('V');
                dfs(h, v - 1);
                path.pop_back();
            }
        };

        dfs(col, row);
        return answer;
    }
};

