class Solution {
    private int count;
    private String answer;
    private char[] path;

    public String kthSmallestPath(int[] destination, int k) {
        int h = destination[1], v = destination[0];
        path = new char[h + v];
        dfs(h, v, 0, k);
        return answer;
    }

    private void dfs(int h, int v, int depth, int k) {
        if (answer != null) return;
        if (h == 0 && v == 0) {
            if (++count == k) answer = new String(path);
            return;
        }
        if (h > 0) {
            path[depth] = 'H';
            dfs(h - 1, v, depth + 1, k);
            if (answer != null) return;
        }
        if (v > 0) {
            path[depth] = 'V';
            dfs(h, v - 1, depth + 1, k);
        }
    }
}

