class Solution:
    def kthSmallestPath(self, destination: List[int], k: int) -> str:
        row, col = destination
        L = row + col
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j]
        ans = []
        for _ in range(L):
            if col > 0:
                take_h = C[row + col - 1][row]
                if k <= take_h:
                    ans.append('H')
                    col -= 1
                else:
                    k -= take_h
                    ans.append('V')
                    row -= 1
            else:
                ans.append('V')
                row -= 1
        return ''.join(ans)

