class Solution {
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int row = destination[0], col = destination[1];
        int L = row + col;
        vector<vector<long long>> C(L + 1, vector<long long>(L + 1, 0));
        for (int i = 0; i <= L; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
        string ans;
        for (int step = 0; step < L; ++step) {
            if (col > 0) {
                long long takeH = C[row + col - 1][row];
                if ((long long)k <= takeH) {
                    ans.push_back('H');
                    --col;
                } else {
                    k -= (int)takeH;
                    ans.push_back('V');
                    --row;
                }
            } else {
                ans.push_back('V');
                --row;
            }
        }
        return ans;
    }
};

