    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0], col = destination[1];
        int L = row + col;
        long[][] C = new long[L + 1][L + 1];
        for (int i = 0; i <= L; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++)
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
        StringBuilder ans = new StringBuilder();
        for (int step = 0; step < L; step++) {
            if (col > 0) {
                long takeH = C[row + col - 1][row];
                if (k <= takeH) {
                    ans.append('H');
                    col--;
                } else {
                    k -= (int) takeH;
                    ans.append('V');
                    row--;
                }
            } else {
                ans.append('V');
                row--;
            }
        }
        return ans.toString();
    }
}

